// Recomputes the tool guide's catalog byte figures from a namespaced tools array.
import { readFileSync } from 'node:fs';

const tools = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const bytes = value => Buffer.byteLength(JSON.stringify(value), 'utf8');
const bare = fn => { const { defer_loading, ...rest } = fn; return rest; };

const flat = tools
  .flatMap(tool => tool.type === 'namespace' ? tool.tools : tool.type === 'function' ? [tool] : [])
  .map(bare)
  .sort((a, b) => a.name < b.name ? -1 : 1);
const eager = tools.filter(tool => tool.type === 'function');
const initial = tools.map(tool => { if (tool.type !== 'namespace') return tool; const { tools: _, ...rest } = tool; return rest; });

console.log('functions', flat.length, 'full bytes', bytes(flat));
console.log('without object_import', flat.length - 1, bytes(flat.filter(fn => fn.name !== 'object_import')));
console.log('namespaced wire bytes', bytes(tools));
console.log('initial projection bytes', bytes(initial), 'saving', bytes(flat) - bytes(initial));
console.log('eager', eager.map(fn => fn.name).join(','), eager.reduce((sum, fn) => sum + bytes(bare(fn)), 0));
for (const set of tools.filter(tool => tool.type === 'namespace'))
  console.log('toolset', set.name, set.tools.map(fn => fn.name).join(','), set.tools.reduce((sum, fn) => sum + bytes(bare(fn)), 0));

// OpenRouter's conservative projection: every deferred function keeps its
// name and description. Several plausible shapes, to find the source's one.
const deferred = tools.filter(tool => tool.type === 'namespace').flatMap(set => set.tools);
const shapes = {
  'type+name+description': fn => ({ type: fn.type, name: fn.name, description: fn.description }),
  'type+name+description+defer': fn => ({ type: fn.type, name: fn.name, description: fn.description, defer_loading: true }),
  'name+description': fn => ({ name: fn.name, description: fn.description }),
  'all but parameters': fn => { const { parameters, ...rest } = fn; return rest; },
  'all but parameters and defer': fn => { const { parameters, defer_loading, ...rest } = fn; return rest; },
};
for (const [label, shape] of Object.entries(shapes)) {
  const sorted = [...eager, ...deferred.map(shape)].sort((a, b) => a.name < b.name ? -1 : 1);
  console.log('openrouter', label, 'with search', bytes([...sorted, { type: 'tool_search' }]), 'without', bytes(sorted));
}

